from scipy.linalg import signm

# Test 1: float32 defective matrix
try:
    result1 = signm(np.array([[2, 1], [0, 2]], dtype=np.float32))
    probe("np.array([[2, 1], [0, 2]], dtype=np.float32) passed to signm (defective matrix)", result1)
except Exception as e:
    probe_exception("np.array([[2, 1], [0, 2]], dtype=np.float32) passed to signm (defective matrix)", e)

